customizationCode.web:
/* Caixa maior, para toque confortável no celular */
.nds-input-otp-slot {
  width: 3rem;
  height: 3rem;
  font-size: var(--text-control-lg);
}

/* Respiro maior entre os dois blocos do formato 3+3 */
.nds-input-otp-separator {
  margin-inline: var(--spacing-4);
}

